/*
 * PLAN
 * 1. COMPOSITION: torus knot floating at [0,0.4,0] above a chamfered cylindrical pedestal (top y=-0.35),
 *    contact-shadow disc at y=-0.36, graded 7x6 backdrop at z=-3; headline 1.2 and caption 1.6 below center.
 * 2. LIGHT RIG: rig-top-museum — spot key #fff6ea 75 from above, directional fill #dcd8d0 0.4, point rim 7 back-right; ambient 0.12 floor.
 * 3. MATERIALS: knot = brushed-metal physical PBR (roughness 0.55 x map, metalness 0.55, clearcoat 0.22, anisotropy 0.9 rot 90deg,
 *    TSL scratch-noise roughness jitter); pedestal #14141a rough 0.7 metal 0.35 with accent-red inset strip.
 * 4. MOTION: orbit primitive on load (0.1 rad/s, radius 0.4); weighted-settle entrance 1.04->1.0 power4.out; slow y idle only.
 * 5. FOCAL: the brushed-titanium torus knot — brightest read under the top key; everything else graded below it.
 */
import { Group, Mesh, PlaneGeometry, TorusKnotGeometry, CylinderGeometry, SpotLight, DirectionalLight, PointLight, AmbientLight, Color, MeshBasicNodeMaterial, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec2, float, mix, smoothstep, texture, fract, sin, dot, sub, mul, add, clamp } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const disposables = [];
  const timelines = [];
  const primHandles = [];

  const colors = config.intent?.visualSpec?.colors ?? {};
  const C = {
    background: colors.background ?? '#0b0b10',
    surface: colors.surface ?? '#14141a',
    ink: colors.ink ?? '#16161d',
    paper: colors.paper ?? '#e8ecf2',
    accent: colors.accent ?? '#ff2a38',
  };
  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' }, { at: 0.7, hex: '#101017' }, { at: 1, hex: '#16161d' },
  ];

  // ---- backdropGradient: 7x6 stage plane at z=-3 with vertical 3-stop gradient ----
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const t = uv().y;
    const c0 = vec3(...new Color(stops[0].hex).toArray());
    const c1 = vec3(...new Color(stops[1].hex).toArray());
    const c2 = vec3(...new Color(stops[2].hex).toArray());
    const a0 = float(stops[0].at), a1 = float(stops[1].at), a2 = float(stops[2].at);
    const low = mix(c0, c1, smoothstep(a0, a1, t));
    const grad = mix(low, c2, smoothstep(a1, a2, t));
    // faint top-light pool so the stage never reads flat
    const d = uv().sub(vec2(0.5, 0.72));
    const pool = smoothstep(0.55, 0.0, d.length()).mul(0.08);
    backdropMat.colorNode = grad.add(vec3(pool, pool, pool.mul(1.05)));
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -3);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---- knotSubject: torus knot, brushed-metal PBR with imperfection pass ----
  const knotGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshPhysicalNodeMaterial({
    color: new Color(0xdadde2),
    roughness: 0.55,
    metalness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
  });
  knotMat.anisotropy = 0.9;
  knotMat.anisotropyRotation = Math.PI / 2; // 90 deg to tube direction
  // TSL scratch-noise: 2% value jitter on roughness so highlights break up (swap-proof base * map)
  {
    const p = uv().mul(vec2(180.0, 24.0));
    const n = fract(sin(dot(fract(p), vec2(12.9898, 78.233))).mul(43758.5453));
    const jitter = n.sub(0.5).mul(0.04); // +/-2%
    const streak = sin(uv().x.mul(900.0)).mul(0.02); // brushed micro-streaks
    knotMat.roughnessNode = clamp(float(0.55).add(jitter).add(streak), 0.0, 1.0);
  }
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    // map multiplies over base grade (center 0.9)
    tex.wrapS = tex.wrapT = ctx.THREE.RepeatWrapping;
    const p2 = uv().mul(vec2(180.0, 24.0));
    const n2 = fract(sin(dot(fract(p2), vec2(12.9898, 78.233))).mul(43758.5453));
    knotMat.roughnessNode = clamp(
      texture(tex).r.mul(0.9).mul(0.55).div(0.5).add(n2.sub(0.5).mul(0.04)).add(0.15),
      0.0, 1.0
    );
    knotMat.needsUpdate = true;
    disposables.push(tex);
  });
  const knot = new Mesh(knotGeo, knotMat);
  knot.position.set(0, 0.4, 0);
  group.add(knot);
  disposables.push(knotGeo, knotMat);

  // ---- pedestalMass: chamfered cylinder, surface #14141a, accent inset strip ----
  const pedGroup = new Group();
  const pedBodyGeo = new CylinderGeometry(1.1, 1.1, 0.44, 96);
  const pedMat = new MeshStandardNodeMaterial({ color: new Color(C.surface), roughness: 0.7, metalness: 0.35 });
  const pedBody = new Mesh(pedBodyGeo, pedMat);
  pedBody.position.y = -0.6; // top at -0.38
  pedGroup.add(pedBody);
  // 0.03-unit chamfered top edge catching the key light
  const chamferGeo = new CylinderGeometry(1.07, 1.1, 0.03, 96);
  const chamferMat = new MeshStandardNodeMaterial({ color: new Color(C.surface), roughness: 0.5, metalness: 0.55 });
  const chamfer = new Mesh(chamferGeo, chamferMat);
  chamfer.position.y = -0.365; // top face at y=-0.35
  pedGroup.add(chamfer);
  // signal-red accent: thin emissive inset strip on pedestal face (<=10% frame)
  const stripGeo = new CylinderGeometry(1.102, 1.102, 0.02, 96, 1, true);
  const stripMat = new MeshBasicNodeMaterial();
  stripMat.colorNode = vec3(...new Color(C.accent).toArray()).mul(1.6);
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.y = -0.72;
  pedGroup.add(strip);
  group.add(pedGroup);
  disposables.push(pedBodyGeo, pedMat, chamferGeo, chamferMat, stripGeo, stripMat);

  // ---- contactShadow: radial gradient disc at y=-0.36 (on pedestal top) ----
  const shadowGeo = new PlaneGeometry(3.0, 3.0);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  {
    const d = uv().sub(vec2(0.5, 0.5)).length().mul(3.0); // world-unit distance
    // opacity 0.6 at center falling to 0 over 0.4 units (from knot footprint edge)
    shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
    shadowMat.opacityNode = smoothstep(1.5, 0.4, d).mul(0.6);
  }
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = -0.345;
  group.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---- lightRig: rig-top-museum ----
  const key = new SpotLight(new Color('#fff6ea'), 75, 0, 0.4, 0.5, 2);
  key.position.set(0, 4, 0.2);
  key.target.position.set(0, 0.2, 0);
  group.add(key); group.add(key.target);
  const fill = new DirectionalLight(new Color('#dcd8d0'), 0.4);
  fill.position.set(-2, 1.6, 2.4);
  fill.target.position.set(0, 0.4, 0);
  group.add(fill); group.add(fill.target);
  const rim = new PointLight(new Color('#ffffff'), 7, 8, 2);
  rim.position.set(1.4, 1, -2.2);
  group.add(rim);
  const ambient = new AmbientLight(new Color(C.ink), 0.12);
  group.add(ambient);

  // ---- textBlock: headline + caption via fontAtlas (ASCII, verbatim spec copy) ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? { text: 'Material study 03' };
  const captionItem = items.find((i) => i.role === 'caption') ?? { text: 'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT' };
  const headline = ctx.fontAtlas.createText(String(headlineItem.text), {
    fontSize: headlineItem.typography?.fontSize ?? 68, color: C.paper, align: 'center',
  });
  headline.position.set(0, -1.2, 0.4);
  group.add(headline);
  const caption = ctx.fontAtlas.createText(String(captionItem.text), {
    fontSize: captionItem.typography?.fontSize ?? 18, color: C.paper, align: 'center', letterSpacingPx: 1.5,
  });
  caption.position.set(0, -1.6, 0.4);
  group.add(caption);

  // ---- motionEntrance: weighted-settle + fade-up (no linear easing) ----
  knot.scale.setScalar(1.04);
  const settleTl = gsap.timeline();
  settleTl.to(knot.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
  settleTl.from(knot.position, { y: 0.7, duration: 0.7, ease: 'power3.out' }, 0);
  settleTl.from(headline.position, { y: -1.4, duration: 0.5, ease: 'power2.out' }, 0.15);
  settleTl.from(caption.position, { y: -1.8, duration: 0.5, ease: 'power2.out' }, 0.25);
  timelines.push(settleTl);
  // idle: ONE slow transform — knot y rotation 0.1 rad/s
  const idleTl = gsap.to(knot.rotation, { y: Math.PI * 2, duration: (Math.PI * 2) / 0.1, ease: 'none', repeat: -1 });
  timelines.push(idleTl);

  // ---- primitivesApply: every config.cinematicPrimitives via ctx.primitives ----
  for (const prim of config.cinematicPrimitives ?? []) {
    const h = ctx.primitives[prim.name]?.(group, prim.params ?? {});
    if (h) primHandles.push(h);
  }

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const h of primHandles) h.cleanup?.();
    for (const d of disposables) d.dispose?.();
  };

  return group;
}

/* @spec-manifest
{"elements":[
  {"id":"text.headline.0","where":"textBlock","how":"fontAtlas headline at y=-1.2"},
  {"id":"text.caption.1","where":"textBlock","how":"fontAtlas mono caption at y=-1.6"},
  {"id":"color.background","where":"backdropGradient","how":"gradient stop 0 #0b0b10"},
  {"id":"color.surface","where":"pedestalMass","how":"pedestal body/chamfer color #14141a"},
  {"id":"color.ink","where":"lightRig","how":"ambient floor tinted #16161d"},
  {"id":"color.paper","where":"textBlock","how":"headline and caption color #e8ecf2"},
  {"id":"color.accent","where":"pedestalMass","how":"emissive red inset strip"},
  {"id":"color.gradient","where":"backdropGradient","how":"3-stop vertical TSL gradient"},
  {"id":"effects.spec","where":"knotSubject","how":"brushed PBR knot, imperfection, anisotropy"},
  {"id":"primitive.orbit","where":"primitivesApply","how":"ctx.primitives orbit on load"}
]}
*/
